def is_simple_power(x, n):
    """Return True if x is a simple power of n (i.e., exists integer k >= 0 such that n**k == x)."""
    # Edge cases
    if n <= 0:
        return False
    if x == 1:
        # n**0 == 1 for any n != 0, but per plan, treat n==1 -> True only when x==1
        return True if n != 0 else False
    if n == 1:
        # Only 1**k == 1, so x must be 1 to be a power of 1
        return False
    if x < 1:
        return False

    # Iteratively divide x by n while divisible
    while x % n == 0:
        x //= n
    return x == 1
